<section class="home-hero"><div class="container home-hero-inner"><div class="hero-copy"><div class="eyebrow light-eyebrow">FoodNest local collection</div><h1>Delicious food, delivered with FoodNest.</h1><p>Discover restaurants, explore menus and order your favourite food.</p><div class="location-search-wrap"><div class="hero-search"><span class="location-pin" aria-hidden="true">&#128205;</span><input id="address-input" type="search" autocomplete="off" placeholder="Enter your delivery location" aria-label="Enter your delivery location"><button id="find-button" type="button">Find restaurants</button></div><div id="address-suggestions" class="suggestion-list" role="listbox"></div></div><div class="location-picker"><button id="location-button" class="location-button" type="button">Use current location</button><span class="hero-note">Your coordinates are used to sort FoodNest restaurants.</span></div><p id="location-message" class="hero-note" aria-live="polite">Start typing and select a location.</p></div><div class="hero-art" role="img" aria-label="Fresh food on a table"><div class="hero-art-badge"><strong>Six local restaurants</strong><span>Complete FoodNest menus</span></div></div></div></section>
<section class="section category-section"><div class="container"><div class="section-heading"><div><div class="eyebrow">Pick a craving</div><h2>Browse by category</h2></div></div><div class="category-grid"><button class="category-tile" data-type="pizza"><img src="assets/images/food-pizza.jpg" alt="Pizza"><span>Pizza</span></button><button class="category-tile" data-type="biryani"><img src="assets/images/foods/chicken-biriyani.jpg" alt="Biryani"><span>Biryani</span></button><button class="category-tile" data-type="burger"><img src="assets/images/food-burger.jpg" alt="Burger"><span>Burger</span></button><button class="category-tile" data-type="south_indian"><img src="assets/images/foods/masala-dosa.jpg" alt="South Indian food"><span>South Indian</span></button><button class="category-tile" data-type="chinese"><img src="assets/images/food-burger.jpg" alt="Chinese food"><span>Chinese</span></button><button class="category-tile" data-type="dessert"><img src="assets/images/food-dessert.jpg" alt="Desserts"><span>Desserts</span></button></div></div></section>
<section class="section nearby-section" id="nearby-results"><div class="container"><div class="section-heading"><div><div class="eyebrow">FoodNest collection</div><h2 id="nearby-heading">Restaurants near you</h2></div><span id="source-indicator" class="section-note">No location selected</span></div><div id="restaurant-results" class="restaurant-grid"><div class="empty-state"><span class="empty-icon">01</span><h3>Choose a location first</h3><p>We will show the six FoodNest demo restaurants sorted by distance.</p></div></div></div></section>
<script>
let coordinates=null,selectedAddress='',places=[],selectedType='',autocompleteTimer=null;
const input=document.querySelector('#address-input'),suggestions=document.querySelector('#address-suggestions'),message=document.querySelector('#location-message');
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function placePhoto(place){const image=place.image||place.photo;return image?`<img class="place-photo" src="${escapeHtml(image)}" alt="${escapeHtml(place.name)}" onerror="this.replaceWith(Object.assign(document.createElement('div'),{className:'place-photo placeholder',textContent:'No restaurant image available'}))">`:'<div class="place-photo placeholder"><span>No restaurant image available</span></div>';}
function placeCard(place){const rating=place.rating===null?'Rating not available':`★ ${Number(place.rating).toFixed(1)}`;const type=(place.cuisine||'Restaurant').replaceAll('_',' ');const distance=place.distance_km===null?'Distance not available':`${Number(place.distance_km).toFixed(1)} km away`;const status=place.open_now===null?'Status unavailable':(place.open_now?'Open':'Closed');const link=`restaurant.php?id=${Number(place.foodnest_restaurant_id)}`;return `<article class="restaurant-card">${placePhoto(place)}<div class="restaurant-info"><div class="restaurant-title"><h3>${escapeHtml(place.name)}</h3><span>${escapeHtml(rating)}</span></div><p class="cuisine-line">${escapeHtml(type)}</p><p class="muted">${escapeHtml(place.formatted_address)}</p><div class="restaurant-meta"><span>${distance}</span><span>${escapeHtml(place.delivery_time||'Delivery time unavailable')}</span><span class="${place.open_now?'open':'closed'}">${status}</span></div><a class="button small" href="${link}">View Menu</a></div></article>`;}
function renderPlaces(){const filtered=selectedType?places.filter(place=>(place.cuisine||place.primary_type||'').toLowerCase().includes(selectedType.replace('_',' '))):places;document.querySelector('#restaurant-results').innerHTML=filtered.length?filtered.map(placeCard).join(''):'<div class="empty-state"><h3>No restaurants found near this location.</h3><p>Try another location or category.</p></div>';}
async function getSuggestions(value){if(value.trim().length<2){suggestions.innerHTML='';return;}try{const response=await fetch('api/place_autocomplete.php?q='+encodeURIComponent(value));const result=await response.json();if(!result.success){suggestions.innerHTML=`<div class="suggestion-error">${escapeHtml(result.message)}</div>`;return;}suggestions.innerHTML=result.suggestions.map(item=>`<button type="button" class="suggestion-item" data-lat="${item.latitude}" data-lon="${item.longitude}" data-address="${escapeHtml(item.display_name)}"><span class="suggestion-pin">&#128205;</span>${escapeHtml(item.display_name)}</button>`).join('');}catch(error){suggestions.innerHTML='<div class="suggestion-error">Location search failed.</div>';}}
function selectSuggestion(button){coordinates={latitude:Number(button.dataset.lat),longitude:Number(button.dataset.lon)};selectedAddress=button.dataset.address;input.value=selectedAddress;suggestions.innerHTML='';sessionStorage.setItem('foodnest_location',JSON.stringify({address:selectedAddress,...coordinates}));message.textContent=`Location selected: ${selectedAddress}`;fetch('api/save_location.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({address:selectedAddress,latitude:coordinates.latitude,longitude:coordinates.longitude})});}
async function loadNearby(){if(!coordinates){message.textContent='Select a suggested location before searching.';return;}document.querySelector('#source-indicator').textContent='Sorting FoodNest restaurants...';const response=await fetch('api/nearby_restaurants.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({latitude:coordinates.latitude,longitude:coordinates.longitude,radius:'5000'})});const result=await response.json();if(!result.success){places=[];document.querySelector('#source-indicator').textContent='FoodNest search error';document.querySelector('#restaurant-results').innerHTML=`<div class="empty-state"><h3>${escapeHtml(result.message)}</h3></div>`;return;}places=result.restaurants;document.querySelector('#source-indicator').textContent='FoodNest Database';document.querySelector('#nearby-heading').textContent=`Restaurants near ${selectedAddress||'your location'}`;renderPlaces();document.querySelector('#nearby-results').scrollIntoView({behavior:'smooth'});}
input.addEventListener('input',()=>{coordinates=null;selectedAddress='';places=[];document.querySelector('#restaurant-results').innerHTML='<div class="empty-state"><h3>Select a new location to refresh results.</h3></div>';sessionStorage.removeItem('foodnest_location');clearTimeout(autocompleteTimer);autocompleteTimer=setTimeout(()=>getSuggestions(input.value),250);});suggestions.addEventListener('click',event=>{const button=event.target.closest('.suggestion-item');if(button)selectSuggestion(button);});document.querySelector('#find-button').addEventListener('click',loadNearby);document.querySelector('#location-button').addEventListener('click',()=>{if(!navigator.geolocation){message.textContent='Location is unavailable in this browser.';return;}message.textContent='Requesting location permission...';navigator.geolocation.getCurrentPosition(position=>{coordinates={latitude:position.coords.latitude,longitude:position.coords.longitude};selectedAddress='your current location';message.textContent='Current location selected.';loadNearby();},()=>{message.textContent='Location access was not allowed. Enter an address instead.';});});document.querySelectorAll('[data-type]').forEach(button=>button.addEventListener('click',()=>{selectedType=button.dataset.type;document.querySelectorAll('[data-type]').forEach(item=>item.classList.remove('active'));button.classList.add('active');renderPlaces();}));
</script>
